const int LIVING  = 16;
const int BEDROOM = 17;
const int PORCH   = 18;

NODRIX_WRITE("light_living")  { digitalWrite(LIVING,  value.asBool()); }
NODRIX_WRITE("light_bedroom") { digitalWrite(BEDROOM, value.asBool()); }
NODRIX_WRITE("light_porch")   { digitalWrite(PORCH,   value.asBool()); }

void setup() {
  pinMode(LIVING,  OUTPUT);
  pinMode(BEDROOM, OUTPUT);
  pinMode(PORCH,   OUTPUT);
  Nodrix.begin(WIFI_SSID, WIFI_PASS, HOST, TOKEN);
}

void loop() {
